insert into public.ll_lesson_index(id,course_id,chapter,position,title,summary,minutes,required_plan) values ('lua-34','lua','Lua sicher anwenden',534,'Werte und Typen prüfen','type liefert den Typ eines Werts. Strings und Zahlen dürfen nicht ungeprüft vermischt werden.',12,'free') on conflict (id) do nothing;
insert into public.ll_lesson_content(lesson_id,payload) values ('lua-34','{"id": "lua-34", "courseId": "lua", "title": "Werte und Typen prüfen", "lang": "lua", "level": "Fortgeschritten", "chapterId": "lua-extension", "goal": "Du kannst werte und typen prüfen erklären und in einem eigenen Beispiel anwenden.", "theory": "type liefert den Typ eines Werts. Strings und Zahlen dürfen nicht ungeprüft vermischt werden. Lies den Beispielcode Zeile für Zeile. Überlege, welche Eingabe das Ergebnis verändert und welcher Fehler möglich ist.", "keyPoints": ["type liefert den Typ eines Werts. Strings und Zahlen dürfen nicht ungeprüft vermischt werden.", "Prüfe zuerst die Eingaben und den Fehlerfall, bevor du die Funktion in einer Resource verwendest."], "task": "Schreibe die gezeigte Lösung eigenständig und erzeuge die Ausgabe number. Erkläre anschließend, welche Zeile den entscheidenden Wert erzeugt.", "example": "local amount = 42\nprint(type(amount))", "starter": "-- Deine Lösung\n", "solution": "local amount = 42\nprint(type(amount))", "checks": ["type", "local"], "hint": "Beginne mit dem ersten Wert und verfolge ihn bis zur Ausgabe. Vergleiche die Schreibweise mit dem Beispiel.", "mistake": "Ein kopierter Codeblock ohne Verständnis reicht nicht: prüfe Datentypen, Grenzen und Fehlerfall.", "quiz": "Was ist in diesem Thema besonders wichtig?", "options": ["Eingaben und Fehlerfälle prüfen, bevor Daten verarbeitet werden.", "Client-Daten sind automatisch sicher.", "Code braucht nie Tests."], "correct": 0, "reviewPrompt": "Welche Eingabe würde bei Werte und Typen prüfen einen Fehler auslösen?", "duration": 12, "category": "Sprachen", "solutionOutput": "number"}'::jsonb) on conflict (lesson_id) do nothing;
insert into public.ll_lesson_index(id,course_id,chapter,position,title,summary,minutes,required_plan) values ('lua-35','lua','Lua sicher anwenden',535,'Zahlen sicher umwandeln','tonumber wandelt einen String in eine Zahl um oder gibt nil zurück. Prüfe nil vor jeder Rechnung.',12,'free') on conflict (id) do nothing;
insert into public.ll_lesson_content(lesson_id,payload) values ('lua-35','{"id": "lua-35", "courseId": "lua", "title": "Zahlen sicher umwandeln", "lang": "lua", "level": "Fortgeschritten", "chapterId": "lua-extension", "goal": "Du kannst zahlen sicher umwandeln erklären und in einem eigenen Beispiel anwenden.", "theory": "tonumber wandelt einen String in eine Zahl um oder gibt nil zurück. Prüfe nil vor jeder Rechnung. Lies den Beispielcode Zeile für Zeile. Überlege, welche Eingabe das Ergebnis verändert und welcher Fehler möglich ist.", "keyPoints": ["tonumber wandelt einen String in eine Zahl um oder gibt nil zurück. Prüfe nil vor jeder Rechnung.", "Prüfe zuerst die Eingaben und den Fehlerfall, bevor du die Funktion in einer Resource verwendest."], "task": "Schreibe die gezeigte Lösung eigenständig und erzeuge die Ausgabe 42. Erkläre anschließend, welche Zeile den entscheidenden Wert erzeugt.", "example": "local amount = tonumber(\"42\")\nif amount then print(amount) end", "starter": "-- Deine Lösung\n", "solution": "local amount = tonumber(\"42\")\nif amount then print(amount) end", "checks": ["tonumber", "local"], "hint": "Beginne mit dem ersten Wert und verfolge ihn bis zur Ausgabe. Vergleiche die Schreibweise mit dem Beispiel.", "mistake": "Ein kopierter Codeblock ohne Verständnis reicht nicht: prüfe Datentypen, Grenzen und Fehlerfall.", "quiz": "Was ist in diesem Thema besonders wichtig?", "options": ["Eingaben und Fehlerfälle prüfen, bevor Daten verarbeitet werden.", "Client-Daten sind automatisch sicher.", "Code braucht nie Tests."], "correct": 0, "reviewPrompt": "Welche Eingabe würde bei Zahlen sicher umwandeln einen Fehler auslösen?", "duration": 12, "category": "Sprachen", "solutionOutput": "42"}'::jsonb) on conflict (lesson_id) do nothing;
insert into public.ll_lesson_index(id,course_id,chapter,position,title,summary,minutes,required_plan) values ('lua-36','lua','Lua sicher anwenden',536,'Strings sicher umwandeln','tostring formt einen Wert für eine Ausgabe um. Ein Benutzerwert bleibt dennoch untrusted input.',12,'free') on conflict (id) do nothing;
insert into public.ll_lesson_content(lesson_id,payload) values ('lua-36','{"id": "lua-36", "courseId": "lua", "title": "Strings sicher umwandeln", "lang": "lua", "level": "Fortgeschritten", "chapterId": "lua-extension", "goal": "Du kannst strings sicher umwandeln erklären und in einem eigenen Beispiel anwenden.", "theory": "tostring formt einen Wert für eine Ausgabe um. Ein Benutzerwert bleibt dennoch untrusted input. Lies den Beispielcode Zeile für Zeile. Überlege, welche Eingabe das Ergebnis verändert und welcher Fehler möglich ist.", "keyPoints": ["tostring formt einen Wert für eine Ausgabe um. Ein Benutzerwert bleibt dennoch untrusted input.", "Prüfe zuerst die Eingaben und den Fehlerfall, bevor du die Funktion in einer Resource verwendest."], "task": "Schreibe die gezeigte Lösung eigenständig und erzeuge die Ausgabe 42. Erkläre anschließend, welche Zeile den entscheidenden Wert erzeugt.", "example": "local amount = 42\nprint(tostring(amount))", "starter": "-- Deine Lösung\n", "solution": "local amount = 42\nprint(tostring(amount))", "checks": ["tostring", "local"], "hint": "Beginne mit dem ersten Wert und verfolge ihn bis zur Ausgabe. Vergleiche die Schreibweise mit dem Beispiel.", "mistake": "Ein kopierter Codeblock ohne Verständnis reicht nicht: prüfe Datentypen, Grenzen und Fehlerfall.", "quiz": "Was ist in diesem Thema besonders wichtig?", "options": ["Eingaben und Fehlerfälle prüfen, bevor Daten verarbeitet werden.", "Client-Daten sind automatisch sicher.", "Code braucht nie Tests."], "correct": 0, "reviewPrompt": "Welche Eingabe würde bei Strings sicher umwandeln einen Fehler auslösen?", "duration": 12, "category": "Sprachen", "solutionOutput": "42"}'::jsonb) on conflict (lesson_id) do nothing;
