insert into public.ll_lesson_content(lesson_id,payload) values ('lua-37','{"id": "lua-37", "courseId": "lua", "title": "Lokaler Gültigkeitsbereich", "lang": "lua", "level": "Fortgeschritten", "chapterId": "lua-extension", "goal": "Du kannst lokaler gültigkeitsbereich erklären und in einem eigenen Beispiel anwenden.", "theory": "local begrenzt eine Variable auf ihren Block. So überschreibst du keine globalen Werte. Lies den Beispielcode Zeile für Zeile. Überlege, welche Eingabe das Ergebnis verändert und welcher Fehler möglich ist.", "keyPoints": ["local begrenzt eine Variable auf ihren Block. So überschreibst du keine globalen Werte.", "Prüfe zuerst die Eingaben und den Fehlerfall, bevor du die Funktion in einer Resource verwendest."], "task": "Schreibe die gezeigte Lösung eigenständig und erzeuge die Ausgabe 5. Erkläre anschließend, welche Zeile den entscheidenden Wert erzeugt.", "example": "local coins = 5\nprint(coins)", "starter": "-- Deine Lösung\n", "solution": "local coins = 5\nprint(coins)", "checks": ["local"], "hint": "Beginne mit dem ersten Wert und verfolge ihn bis zur Ausgabe. Vergleiche die Schreibweise mit dem Beispiel.", "mistake": "Ein kopierter Codeblock ohne Verständnis reicht nicht: prüfe Datentypen, Grenzen und Fehlerfall.", "quiz": "Was ist in diesem Thema besonders wichtig?", "options": ["Eingaben und Fehlerfälle prüfen, bevor Daten verarbeitet werden.", "Client-Daten sind automatisch sicher.", "Code braucht nie Tests."], "correct": 0, "reviewPrompt": "Welche Eingabe würde bei Lokaler Gültigkeitsbereich einen Fehler auslösen?", "duration": 12, "category": "Sprachen", "solutionOutput": "5"}'::jsonb) on conflict (lesson_id) do nothing;
insert into public.ll_lesson_index(id,course_id,chapter,position,title,summary,minutes,required_plan) values ('lua-38','lua','Lua sicher anwenden',538,'nil und Standardwerte','nil bedeutet, dass ein Wert fehlt. Ein Standardwert verhindert Folgefehler.',12,'free') on conflict (id) do nothing;
insert into public.ll_lesson_content(lesson_id,payload) values ('lua-38','{"id": "lua-38", "courseId": "lua", "title": "nil und Standardwerte", "lang": "lua", "level": "Fortgeschritten", "chapterId": "lua-extension", "goal": "Du kannst nil und standardwerte erklären und in einem eigenen Beispiel anwenden.", "theory": "nil bedeutet, dass ein Wert fehlt. Ein Standardwert verhindert Folgefehler. Lies den Beispielcode Zeile für Zeile. Überlege, welche Eingabe das Ergebnis verändert und welcher Fehler möglich ist.", "keyPoints": ["nil bedeutet, dass ein Wert fehlt. Ein Standardwert verhindert Folgefehler.", "Prüfe zuerst die Eingaben und den Fehlerfall, bevor du die Funktion in einer Resource verwendest."], "task": "Schreibe die gezeigte Lösung eigenständig und erzeuge die Ausgabe 0. Erkläre anschließend, welche Zeile den entscheidenden Wert erzeugt.", "example": "local coins = nil\ncoins = coins or 0\nprint(coins)", "starter": "-- Deine Lösung\n", "solution": "local coins = nil\ncoins = coins or 0\nprint(coins)", "checks": ["local", "or"], "hint": "Beginne mit dem ersten Wert und verfolge ihn bis zur Ausgabe. Vergleiche die Schreibweise mit dem Beispiel.", "mistake": "Ein kopierter Codeblock ohne Verständnis reicht nicht: prüfe Datentypen, Grenzen und Fehlerfall.", "quiz": "Was ist in diesem Thema besonders wichtig?", "options": ["Eingaben und Fehlerfälle prüfen, bevor Daten verarbeitet werden.", "Client-Daten sind automatisch sicher.", "Code braucht nie Tests."], "correct": 0, "reviewPrompt": "Welche Eingabe würde bei nil und Standardwerte einen Fehler auslösen?", "duration": 12, "category": "Sprachen", "solutionOutput": "0"}'::jsonb) on conflict (lesson_id) do nothing;
insert into public.ll_lesson_index(id,course_id,chapter,position,title,summary,minutes,required_plan) values ('lua-39','lua','Lua sicher anwenden',539,'Vergleiche mit ==','Ein Vergleich prüft Werte; ein einzelnes = weist Werte zu. Bedingungen brauchen einen booleschen Ausdruck.',12,'free') on conflict (id) do nothing;
insert into public.ll_lesson_content(lesson_id,payload) values ('lua-39','{"id": "lua-39", "courseId": "lua", "title": "Vergleiche mit ==", "lang": "lua", "level": "Fortgeschritten", "chapterId": "lua-extension", "goal": "Du kannst vergleiche mit == erklären und in einem eigenen Beispiel anwenden.", "theory": "Ein Vergleich prüft Werte; ein einzelnes = weist Werte zu. Bedingungen brauchen einen booleschen Ausdruck. Lies den Beispielcode Zeile für Zeile. Überlege, welche Eingabe das Ergebnis verändert und welcher Fehler möglich ist.", "keyPoints": ["Ein Vergleich prüft Werte; ein einzelnes = weist Werte zu. Bedingungen brauchen einen booleschen Ausdruck.", "Prüfe zuerst die Eingaben und den Fehlerfall, bevor du die Funktion in einer Resource verwendest."], "task": "Schreibe die gezeigte Lösung eigenständig und erzeuge die Ausgabe passt. Erkläre anschließend, welche Zeile den entscheidenden Wert erzeugt.", "example": "local coins = 5\nif coins == 5 then print(\"passt\") end", "starter": "-- Deine Lösung\n", "solution": "local coins = 5\nif coins == 5 then print(\"passt\") end", "checks": ["local", "=="], "hint": "Beginne mit dem ersten Wert und verfolge ihn bis zur Ausgabe. Vergleiche die Schreibweise mit dem Beispiel.", "mistake": "Ein kopierter Codeblock ohne Verständnis reicht nicht: prüfe Datentypen, Grenzen und Fehlerfall.", "quiz": "Was ist in diesem Thema besonders wichtig?", "options": ["Eingaben und Fehlerfälle prüfen, bevor Daten verarbeitet werden.", "Client-Daten sind automatisch sicher.", "Code braucht nie Tests."], "correct": 0, "reviewPrompt": "Welche Eingabe würde bei Vergleiche mit == einen Fehler auslösen?", "duration": 12, "category": "Sprachen", "solutionOutput": "passt"}'::jsonb) on conflict (lesson_id) do nothing;
insert into public.ll_lesson_index(id,course_id,chapter,position,title,summary,minutes,required_plan) values ('lua-40','lua','Lua sicher anwenden',540,'Grenzwerte prüfen','Mit >= prüfst du inklusive Grenzwert. Teste auch einen Wert direkt darunter.',12,'plus') on conflict (id) do nothing;
insert into public.ll_lesson_content(lesson_id,payload) values ('lua-40','{"id": "lua-40", "courseId": "lua", "title": "Grenzwerte prüfen", "lang": "lua", "level": "Fortgeschritten", "chapterId": "lua-extension", "goal": "Du kannst grenzwerte prüfen erklären und in einem eigenen Beispiel anwenden.", "theory": "Mit >= prüfst du inklusive Grenzwert. Teste auch einen Wert direkt darunter. Lies den Beispielcode Zeile für Zeile. Überlege, welche Eingabe das Ergebnis verändert und welcher Fehler möglich ist.", "keyPoints": ["Mit >= prüfst du inklusive Grenzwert. Teste auch einen Wert direkt darunter.", "Prüfe zuerst die Eingaben und den Fehlerfall, bevor du die Funktion in einer Resource verwendest."], "task": "Schreibe die gezeigte Lösung eigenständig und erzeuge die Ausgabe genug. Erkläre anschließend, welche Zeile den entscheidenden Wert erzeugt.", "example": "local coins = 5\nif coins >= 5 then print(\"genug\") end", "starter": "-- Deine Lösung\n", "solution": "local coins = 5\nif coins >= 5 then print(\"genug\") end", "checks": ["local", ">="], "hint": "Beginne mit dem ersten Wert und verfolge ihn bis zur Ausgabe. Vergleiche die Schreibweise mit dem Beispiel.", "mistake": "Ein kopierter Codeblock ohne Verständnis reicht nicht: prüfe Datentypen, Grenzen und Fehlerfall.", "quiz": "Was ist in diesem Thema besonders wichtig?", "options": ["Eingaben und Fehlerfälle prüfen, bevor Daten verarbeitet werden.", "Client-Daten sind automatisch sicher.", "Code braucht nie Tests."], "correct": 0, "reviewPrompt": "Welche Eingabe würde bei Grenzwerte prüfen einen Fehler auslösen?", "duration": 12, "category": "Sprachen", "solutionOutput": "genug"}'::jsonb) on conflict (lesson_id) do nothing;
