insert into public.ll_lesson_content(lesson_id,payload) values ('lua-41','{"id": "lua-41", "courseId": "lua", "title": "Mehrere Bedingungen", "lang": "lua", "level": "Fortgeschritten", "chapterId": "lua-extension", "goal": "Du kannst mehrere bedingungen erklären und in einem eigenen Beispiel anwenden.", "theory": "and verlangt beide Bedingungen, or mindestens eine. Klammern machen komplexe Ausdrücke lesbar. Lies den Beispielcode Zeile für Zeile. Überlege, welche Eingabe das Ergebnis verändert und welcher Fehler möglich ist.", "keyPoints": ["and verlangt beide Bedingungen, or mindestens eine. Klammern machen komplexe Ausdrücke lesbar.", "Prüfe zuerst die Eingaben und den Fehlerfall, bevor du die Funktion in einer Resource verwendest."], "task": "Schreibe die gezeigte Lösung eigenständig und erzeuge die Ausgabe ok. Erkläre anschließend, welche Zeile den entscheidenden Wert erzeugt.", "example": "local active = true\nlocal coins = 5\nif active and coins >= 5 then print(\"ok\") end", "starter": "-- Deine Lösung\n", "solution": "local active = true\nlocal coins = 5\nif active and coins >= 5 then print(\"ok\") end", "checks": ["local", ">="], "hint": "Beginne mit dem ersten Wert und verfolge ihn bis zur Ausgabe. Vergleiche die Schreibweise mit dem Beispiel.", "mistake": "Ein kopierter Codeblock ohne Verständnis reicht nicht: prüfe Datentypen, Grenzen und Fehlerfall.", "quiz": "Was ist in diesem Thema besonders wichtig?", "options": ["Eingaben und Fehlerfälle prüfen, bevor Daten verarbeitet werden.", "Client-Daten sind automatisch sicher.", "Code braucht nie Tests."], "correct": 0, "reviewPrompt": "Welche Eingabe würde bei Mehrere Bedingungen einen Fehler auslösen?", "duration": 12, "category": "Sprachen", "solutionOutput": "ok"}'::jsonb) on conflict (lesson_id) do nothing;
insert into public.ll_lesson_index(id,course_id,chapter,position,title,summary,minutes,required_plan) values ('lua-42','lua','Lua sicher anwenden',542,'Frühzeitiger Rücksprung','return beendet eine Funktion. Prüfe ungültige Eingaben früh, bevor Seiteneffekte stattfinden.',12,'plus') on conflict (id) do nothing;
insert into public.ll_lesson_content(lesson_id,payload) values ('lua-42','{"id": "lua-42", "courseId": "lua", "title": "Frühzeitiger Rücksprung", "lang": "lua", "level": "Fortgeschritten", "chapterId": "lua-extension", "goal": "Du kannst frühzeitiger rücksprung erklären und in einem eigenen Beispiel anwenden.", "theory": "return beendet eine Funktion. Prüfe ungültige Eingaben früh, bevor Seiteneffekte stattfinden. Lies den Beispielcode Zeile für Zeile. Überlege, welche Eingabe das Ergebnis verändert und welcher Fehler möglich ist.", "keyPoints": ["return beendet eine Funktion. Prüfe ungültige Eingaben früh, bevor Seiteneffekte stattfinden.", "Prüfe zuerst die Eingaben und den Fehlerfall, bevor du die Funktion in einer Resource verwendest."], "task": "Schreibe die gezeigte Lösung eigenständig und erzeuge die Ausgabe true. Erkläre anschließend, welche Zeile den entscheidenden Wert erzeugt.", "example": "local function valid(n)\n  if not n then return false end\n  return n > 0\nend\nprint(valid(2))", "starter": "-- Deine Lösung\n", "solution": "local function valid(n)\n  if not n then return false end\n  return n > 0\nend\nprint(valid(2))", "checks": ["local", "if"], "hint": "Beginne mit dem ersten Wert und verfolge ihn bis zur Ausgabe. Vergleiche die Schreibweise mit dem Beispiel.", "mistake": "Ein kopierter Codeblock ohne Verständnis reicht nicht: prüfe Datentypen, Grenzen und Fehlerfall.", "quiz": "Was ist in diesem Thema besonders wichtig?", "options": ["Eingaben und Fehlerfälle prüfen, bevor Daten verarbeitet werden.", "Client-Daten sind automatisch sicher.", "Code braucht nie Tests."], "correct": 0, "reviewPrompt": "Welche Eingabe würde bei Frühzeitiger Rücksprung einen Fehler auslösen?", "duration": 12, "category": "Sprachen", "solutionOutput": "true"}'::jsonb) on conflict (lesson_id) do nothing;
insert into public.ll_lesson_index(id,course_id,chapter,position,title,summary,minutes,required_plan) values ('lua-43','lua','Lua sicher anwenden',543,'Funktionen mit Parametern','Parameter übergeben Werte an Funktionen. Die Funktion sollte eine klar benannte Aufgabe erfüllen.',12,'plus') on conflict (id) do nothing;
insert into public.ll_lesson_content(lesson_id,payload) values ('lua-43','{"id": "lua-43", "courseId": "lua", "title": "Funktionen mit Parametern", "lang": "lua", "level": "Fortgeschritten", "chapterId": "lua-extension", "goal": "Du kannst funktionen mit parametern erklären und in einem eigenen Beispiel anwenden.", "theory": "Parameter übergeben Werte an Funktionen. Die Funktion sollte eine klar benannte Aufgabe erfüllen. Lies den Beispielcode Zeile für Zeile. Überlege, welche Eingabe das Ergebnis verändert und welcher Fehler möglich ist.", "keyPoints": ["Parameter übergeben Werte an Funktionen. Die Funktion sollte eine klar benannte Aufgabe erfüllen.", "Prüfe zuerst die Eingaben und den Fehlerfall, bevor du die Funktion in einer Resource verwendest."], "task": "Schreibe die gezeigte Lösung eigenständig und erzeuge die Ausgabe 8. Erkläre anschließend, welche Zeile den entscheidenden Wert erzeugt.", "example": "local function double(n) return n * 2 end\nprint(double(4))", "starter": "-- Deine Lösung\n", "solution": "local function double(n) return n * 2 end\nprint(double(4))", "checks": ["local", "return"], "hint": "Beginne mit dem ersten Wert und verfolge ihn bis zur Ausgabe. Vergleiche die Schreibweise mit dem Beispiel.", "mistake": "Ein kopierter Codeblock ohne Verständnis reicht nicht: prüfe Datentypen, Grenzen und Fehlerfall.", "quiz": "Was ist in diesem Thema besonders wichtig?", "options": ["Eingaben und Fehlerfälle prüfen, bevor Daten verarbeitet werden.", "Client-Daten sind automatisch sicher.", "Code braucht nie Tests."], "correct": 0, "reviewPrompt": "Welche Eingabe würde bei Funktionen mit Parametern einen Fehler auslösen?", "duration": 12, "category": "Sprachen", "solutionOutput": "8"}'::jsonb) on conflict (lesson_id) do nothing;
insert into public.ll_lesson_index(id,course_id,chapter,position,title,summary,minutes,required_plan) values ('lua-44','lua','Lua sicher anwenden',544,'Rückgabewerte nutzen','Eine Funktion kann einen Wert zurückgeben. Speichere und prüfe ihn statt nur auf eine Ausgabe zu schauen.',12,'plus') on conflict (id) do nothing;
insert into public.ll_lesson_content(lesson_id,payload) values ('lua-44','{"id": "lua-44", "courseId": "lua", "title": "Rückgabewerte nutzen", "lang": "lua", "level": "Fortgeschritten", "chapterId": "lua-extension", "goal": "Du kannst rückgabewerte nutzen erklären und in einem eigenen Beispiel anwenden.", "theory": "Eine Funktion kann einen Wert zurückgeben. Speichere und prüfe ihn statt nur auf eine Ausgabe zu schauen. Lies den Beispielcode Zeile für Zeile. Überlege, welche Eingabe das Ergebnis verändert und welcher Fehler möglich ist.", "keyPoints": ["Eine Funktion kann einen Wert zurückgeben. Speichere und prüfe ihn statt nur auf eine Ausgabe zu schauen.", "Prüfe zuerst die Eingaben und den Fehlerfall, bevor du die Funktion in einer Resource verwendest."], "task": "Schreibe die gezeigte Lösung eigenständig und erzeuge die Ausgabe 8. Erkläre anschließend, welche Zeile den entscheidenden Wert erzeugt.", "example": "local function add(a,b) return a+b end\nlocal total = add(3,5)\nprint(total)", "starter": "-- Deine Lösung\n", "solution": "local function add(a,b) return a+b end\nlocal total = add(3,5)\nprint(total)", "checks": ["local", "return"], "hint": "Beginne mit dem ersten Wert und verfolge ihn bis zur Ausgabe. Vergleiche die Schreibweise mit dem Beispiel.", "mistake": "Ein kopierter Codeblock ohne Verständnis reicht nicht: prüfe Datentypen, Grenzen und Fehlerfall.", "quiz": "Was ist in diesem Thema besonders wichtig?", "options": ["Eingaben und Fehlerfälle prüfen, bevor Daten verarbeitet werden.", "Client-Daten sind automatisch sicher.", "Code braucht nie Tests."], "correct": 0, "reviewPrompt": "Welche Eingabe würde bei Rückgabewerte nutzen einen Fehler auslösen?", "duration": 12, "category": "Sprachen", "solutionOutput": "8"}'::jsonb) on conflict (lesson_id) do nothing;
