insert into public.ll_lesson_content(lesson_id,payload) values ('lua-45','{"id": "lua-45", "courseId": "lua", "title": "Listen mit ipairs", "lang": "lua", "level": "Fortgeschritten", "chapterId": "lua-extension", "goal": "Du kannst listen mit ipairs erklären und in einem eigenen Beispiel anwenden.", "theory": "ipairs durchläuft fortlaufende Listeneinträge in Reihenfolge. Tabellen können ab 1 indiziert sein. Lies den Beispielcode Zeile für Zeile. Überlege, welche Eingabe das Ergebnis verändert und welcher Fehler möglich ist.", "keyPoints": ["ipairs durchläuft fortlaufende Listeneinträge in Reihenfolge. Tabellen können ab 1 indiziert sein.", "Prüfe zuerst die Eingaben und den Fehlerfall, bevor du die Funktion in einer Resource verwendest."], "task": "Schreibe die gezeigte Lösung eigenständig und erzeuge die Ausgabe 1 Ana\n2 Ben. Erkläre anschließend, welche Zeile den entscheidenden Wert erzeugt.", "example": "local names = {\"Ana\",\"Ben\"}\nfor i,name in ipairs(names) do print(i,name) end", "starter": "-- Deine Lösung\n", "solution": "local names = {\"Ana\",\"Ben\"}\nfor i,name in ipairs(names) do print(i,name) end", "checks": ["local", "or"], "hint": "Beginne mit dem ersten Wert und verfolge ihn bis zur Ausgabe. Vergleiche die Schreibweise mit dem Beispiel.", "mistake": "Ein kopierter Codeblock ohne Verständnis reicht nicht: prüfe Datentypen, Grenzen und Fehlerfall.", "quiz": "Was ist in diesem Thema besonders wichtig?", "options": ["Eingaben und Fehlerfälle prüfen, bevor Daten verarbeitet werden.", "Client-Daten sind automatisch sicher.", "Code braucht nie Tests."], "correct": 0, "reviewPrompt": "Welche Eingabe würde bei Listen mit ipairs einen Fehler auslösen?", "duration": 12, "category": "Sprachen", "solutionOutput": "1 Ana\n2 Ben"}'::jsonb) on conflict (lesson_id) do nothing;
