insert into public.ll_lesson_content(lesson_id,payload) values ('lua-46','{"id": "lua-46", "courseId": "lua", "title": "Schlüssel mit pairs", "lang": "lua", "level": "Fortgeschritten", "chapterId": "lua-extension", "goal": "Du kannst schlüssel mit pairs erklären und in einem eigenen Beispiel anwenden.", "theory": "pairs durchläuft Schlüssel und Werte. Die Reihenfolge ist dabei nicht garantiert. Lies den Beispielcode Zeile für Zeile. Überlege, welche Eingabe das Ergebnis verändert und welcher Fehler möglich ist.", "keyPoints": ["pairs durchläuft Schlüssel und Werte. Die Reihenfolge ist dabei nicht garantiert.", "Prüfe zuerst die Eingaben und den Fehlerfall, bevor du die Funktion in einer Resource verwendest."], "task": "Schreibe die gezeigte Lösung eigenständig und erzeuge die Ausgabe name Ana. Erkläre anschließend, welche Zeile den entscheidenden Wert erzeugt.", "example": "local user = {name=\"Ana\"}\nfor key,value in pairs(user) do print(key,value) end", "starter": "-- Deine Lösung\n", "solution": "local user = {name=\"Ana\"}\nfor key,value in pairs(user) do print(key,value) end", "checks": ["local", "or"], "hint": "Beginne mit dem ersten Wert und verfolge ihn bis zur Ausgabe. Vergleiche die Schreibweise mit dem Beispiel.", "mistake": "Ein kopierter Codeblock ohne Verständnis reicht nicht: prüfe Datentypen, Grenzen und Fehlerfall.", "quiz": "Was ist in diesem Thema besonders wichtig?", "options": ["Eingaben und Fehlerfälle prüfen, bevor Daten verarbeitet werden.", "Client-Daten sind automatisch sicher.", "Code braucht nie Tests."], "correct": 0, "reviewPrompt": "Welche Eingabe würde bei Schlüssel mit pairs einen Fehler auslösen?", "duration": 12, "category": "Sprachen", "solutionOutput": "name Ana"}'::jsonb) on conflict (lesson_id) do nothing;
