insert into public.ll_lesson_content(lesson_id,payload) values ('lua-47','{"id": "lua-47", "courseId": "lua", "title": "Einträge hinzufügen", "lang": "lua", "level": "Fortgeschritten", "chapterId": "lua-extension", "goal": "Du kannst einträge hinzufügen erklären und in einem eigenen Beispiel anwenden.", "theory": "table.insert hängt einen Wert an eine Liste an. Achte auf den Index und auf doppelte Einträge. Lies den Beispielcode Zeile für Zeile. Überlege, welche Eingabe das Ergebnis verändert und welcher Fehler möglich ist.", "keyPoints": ["table.insert hängt einen Wert an eine Liste an. Achte auf den Index und auf doppelte Einträge.", "Prüfe zuerst die Eingaben und den Fehlerfall, bevor du die Funktion in einer Resource verwendest."], "task": "Schreibe die gezeigte Lösung eigenständig und erzeuge die Ausgabe Ana. Erkläre anschließend, welche Zeile den entscheidenden Wert erzeugt.", "example": "local names = {}\ntable.insert(names,\"Ana\")\nprint(names[1])", "starter": "-- Deine Lösung\n", "solution": "local names = {}\ntable.insert(names,\"Ana\")\nprint(names[1])", "checks": ["local", "table.insert"], "hint": "Beginne mit dem ersten Wert und verfolge ihn bis zur Ausgabe. Vergleiche die Schreibweise mit dem Beispiel.", "mistake": "Ein kopierter Codeblock ohne Verständnis reicht nicht: prüfe Datentypen, Grenzen und Fehlerfall.", "quiz": "Was ist in diesem Thema besonders wichtig?", "options": ["Eingaben und Fehlerfälle prüfen, bevor Daten verarbeitet werden.", "Client-Daten sind automatisch sicher.", "Code braucht nie Tests."], "correct": 0, "reviewPrompt": "Welche Eingabe würde bei Einträge hinzufügen einen Fehler auslösen?", "duration": 12, "category": "Sprachen", "solutionOutput": "Ana"}'::jsonb) on conflict (lesson_id) do nothing;
