insert into public.ll_lesson_content(lesson_id,payload) values ('lua-48','{"id": "lua-48", "courseId": "lua", "title": "Einträge entfernen", "lang": "lua", "level": "Fortgeschritten", "chapterId": "lua-extension", "goal": "Du kannst einträge entfernen erklären und in einem eigenen Beispiel anwenden.", "theory": "table.remove verändert die Tabelle und gibt den entfernten Wert zurück. Prüfe den Index vorher. Lies den Beispielcode Zeile für Zeile. Überlege, welche Eingabe das Ergebnis verändert und welcher Fehler möglich ist.", "keyPoints": ["table.remove verändert die Tabelle und gibt den entfernten Wert zurück. Prüfe den Index vorher.", "Prüfe zuerst die Eingaben und den Fehlerfall, bevor du die Funktion in einer Resource verwendest."], "task": "Schreibe die gezeigte Lösung eigenständig und erzeuge die Ausgabe Ana. Erkläre anschließend, welche Zeile den entscheidenden Wert erzeugt.", "example": "local names = {\"Ana\",\"Ben\"}\nlocal removed = table.remove(names,1)\nprint(removed)", "starter": "-- Deine Lösung\n", "solution": "local names = {\"Ana\",\"Ben\"}\nlocal removed = table.remove(names,1)\nprint(removed)", "checks": ["local", "table.remove"], "hint": "Beginne mit dem ersten Wert und verfolge ihn bis zur Ausgabe. Vergleiche die Schreibweise mit dem Beispiel.", "mistake": "Ein kopierter Codeblock ohne Verständnis reicht nicht: prüfe Datentypen, Grenzen und Fehlerfall.", "quiz": "Was ist in diesem Thema besonders wichtig?", "options": ["Eingaben und Fehlerfälle prüfen, bevor Daten verarbeitet werden.", "Client-Daten sind automatisch sicher.", "Code braucht nie Tests."], "correct": 0, "reviewPrompt": "Welche Eingabe würde bei Einträge entfernen einen Fehler auslösen?", "duration": 12, "category": "Sprachen", "solutionOutput": "Ana"}'::jsonb) on conflict (lesson_id) do nothing;
