insert into public.ll_lesson_content(lesson_id,payload) values ('lua-49','{"id": "lua-49", "courseId": "lua", "title": "Länge einer Liste", "lang": "lua", "level": "Fortgeschritten", "chapterId": "lua-extension", "goal": "Du kannst länge einer liste erklären und in einem eigenen Beispiel anwenden.", "theory": "Der Längenoperator # ist für dichte Listen gedacht. Bei Tabellen mit Lücken ist er nicht zuverlässig. Lies den Beispielcode Zeile für Zeile. Überlege, welche Eingabe das Ergebnis verändert und welcher Fehler möglich ist.", "keyPoints": ["Der Längenoperator # ist für dichte Listen gedacht. Bei Tabellen mit Lücken ist er nicht zuverlässig.", "Prüfe zuerst die Eingaben und den Fehlerfall, bevor du die Funktion in einer Resource verwendest."], "task": "Schreibe die gezeigte Lösung eigenständig und erzeuge die Ausgabe 2. Erkläre anschließend, welche Zeile den entscheidenden Wert erzeugt.", "example": "local names = {\"Ana\",\"Ben\"}\nprint(#names)", "starter": "-- Deine Lösung\n", "solution": "local names = {\"Ana\",\"Ben\"}\nprint(#names)", "checks": ["local", "#"], "hint": "Beginne mit dem ersten Wert und verfolge ihn bis zur Ausgabe. Vergleiche die Schreibweise mit dem Beispiel.", "mistake": "Ein kopierter Codeblock ohne Verständnis reicht nicht: prüfe Datentypen, Grenzen und Fehlerfall.", "quiz": "Was ist in diesem Thema besonders wichtig?", "options": ["Eingaben und Fehlerfälle prüfen, bevor Daten verarbeitet werden.", "Client-Daten sind automatisch sicher.", "Code braucht nie Tests."], "correct": 0, "reviewPrompt": "Welche Eingabe würde bei Länge einer Liste einen Fehler auslösen?", "duration": 12, "category": "Sprachen", "solutionOutput": "2"}'::jsonb) on conflict (lesson_id) do nothing;
