insert into public.ll_lesson_content(lesson_id,payload) values ('lua-50','{"id": "lua-50", "courseId": "lua", "title": "String-Muster finden", "lang": "lua", "level": "Fortgeschritten", "chapterId": "lua-extension", "goal": "Du kannst string-muster finden erklären und in einem eigenen Beispiel anwenden.", "theory": "string.find liefert die Position oder nil. Verwende klare Muster und prüfe den Rückgabewert. Lies den Beispielcode Zeile für Zeile. Überlege, welche Eingabe das Ergebnis verändert und welcher Fehler möglich ist.", "keyPoints": ["string.find liefert die Position oder nil. Verwende klare Muster und prüfe den Rückgabewert.", "Prüfe zuerst die Eingaben und den Fehlerfall, bevor du die Funktion in einer Resource verwendest."], "task": "Schreibe die gezeigte Lösung eigenständig und erzeuge die Ausgabe 7. Erkläre anschließend, welche Zeile den entscheidenden Wert erzeugt.", "example": "local at = string.find(\"LiveryLab\",\"Lab\")\nprint(at)", "starter": "-- Deine Lösung\n", "solution": "local at = string.find(\"LiveryLab\",\"Lab\")\nprint(at)", "checks": ["local", "string.find"], "hint": "Beginne mit dem ersten Wert und verfolge ihn bis zur Ausgabe. Vergleiche die Schreibweise mit dem Beispiel.", "mistake": "Ein kopierter Codeblock ohne Verständnis reicht nicht: prüfe Datentypen, Grenzen und Fehlerfall.", "quiz": "Was ist in diesem Thema besonders wichtig?", "options": ["Eingaben und Fehlerfälle prüfen, bevor Daten verarbeitet werden.", "Client-Daten sind automatisch sicher.", "Code braucht nie Tests."], "correct": 0, "reviewPrompt": "Welche Eingabe würde bei String-Muster finden einen Fehler auslösen?", "duration": 12, "category": "Sprachen", "solutionOutput": "7"}'::jsonb) on conflict (lesson_id) do nothing;
