insert into public.ll_lesson_content(lesson_id,payload) values ('lua-51','{"id": "lua-51", "courseId": "lua", "title": "String-Teile lesen", "lang": "lua", "level": "Fortgeschritten", "chapterId": "lua-extension", "goal": "Du kannst string-teile lesen erklären und in einem eigenen Beispiel anwenden.", "theory": "string.sub schneidet eine Zeichenfolge anhand inklusiver Indizes. Lua zählt ab 1. Lies den Beispielcode Zeile für Zeile. Überlege, welche Eingabe das Ergebnis verändert und welcher Fehler möglich ist.", "keyPoints": ["string.sub schneidet eine Zeichenfolge anhand inklusiver Indizes. Lua zählt ab 1.", "Prüfe zuerst die Eingaben und den Fehlerfall, bevor du die Funktion in einer Resource verwendest."], "task": "Schreibe die gezeigte Lösung eigenständig und erzeuge die Ausgabe Livery. Erkläre anschließend, welche Zeile den entscheidenden Wert erzeugt.", "example": "print(string.sub(\"LiveryLab\",1,6))", "starter": "-- Deine Lösung\n", "solution": "print(string.sub(\"LiveryLab\",1,6))", "checks": ["string.sub"], "hint": "Beginne mit dem ersten Wert und verfolge ihn bis zur Ausgabe. Vergleiche die Schreibweise mit dem Beispiel.", "mistake": "Ein kopierter Codeblock ohne Verständnis reicht nicht: prüfe Datentypen, Grenzen und Fehlerfall.", "quiz": "Was ist in diesem Thema besonders wichtig?", "options": ["Eingaben und Fehlerfälle prüfen, bevor Daten verarbeitet werden.", "Client-Daten sind automatisch sicher.", "Code braucht nie Tests."], "correct": 0, "reviewPrompt": "Welche Eingabe würde bei String-Teile lesen einen Fehler auslösen?", "duration": 12, "category": "Sprachen", "solutionOutput": "Livery"}'::jsonb) on conflict (lesson_id) do nothing;
