insert into public.ll_lesson_content(lesson_id,payload) values ('lua-52','{"id": "lua-52", "courseId": "lua", "title": "Text formatieren", "lang": "lua", "level": "Fortgeschritten", "chapterId": "lua-extension", "goal": "Du kannst text formatieren erklären und in einem eigenen Beispiel anwenden.", "theory": "string.format baut eine lesbare Ausgabe aus Platzhaltern. %s steht für Text, %d für ganze Zahlen. Lies den Beispielcode Zeile für Zeile. Überlege, welche Eingabe das Ergebnis verändert und welcher Fehler möglich ist.", "keyPoints": ["string.format baut eine lesbare Ausgabe aus Platzhaltern. %s steht für Text, %d für ganze Zahlen.", "Prüfe zuerst die Eingaben und den Fehlerfall, bevor du die Funktion in einer Resource verwendest."], "task": "Schreibe die gezeigte Lösung eigenständig und erzeuge die Ausgabe Coins: 5. Erkläre anschließend, welche Zeile den entscheidenden Wert erzeugt.", "example": "local text = string.format(\"%s: %d\", \"Coins\", 5)\nprint(text)", "starter": "-- Deine Lösung\n", "solution": "local text = string.format(\"%s: %d\", \"Coins\", 5)\nprint(text)", "checks": ["local", "or"], "hint": "Beginne mit dem ersten Wert und verfolge ihn bis zur Ausgabe. Vergleiche die Schreibweise mit dem Beispiel.", "mistake": "Ein kopierter Codeblock ohne Verständnis reicht nicht: prüfe Datentypen, Grenzen und Fehlerfall.", "quiz": "Was ist in diesem Thema besonders wichtig?", "options": ["Eingaben und Fehlerfälle prüfen, bevor Daten verarbeitet werden.", "Client-Daten sind automatisch sicher.", "Code braucht nie Tests."], "correct": 0, "reviewPrompt": "Welche Eingabe würde bei Text formatieren einen Fehler auslösen?", "duration": 12, "category": "Sprachen", "solutionOutput": "Coins: 5"}'::jsonb) on conflict (lesson_id) do nothing;
