insert into public.ll_lesson_content(lesson_id,payload) values ('lua-53','{"id": "lua-53", "courseId": "lua", "title": "Fehler kontrolliert behandeln", "lang": "lua", "level": "Fortgeschritten", "chapterId": "lua-extension", "goal": "Du kannst fehler kontrolliert behandeln erklären und in einem eigenen Beispiel anwenden.", "theory": "pcall fängt Laufzeitfehler einer Funktion ab und liefert Erfolg plus Ergebnis. Logge Fehler ohne Geheimnisse. Lies den Beispielcode Zeile für Zeile. Überlege, welche Eingabe das Ergebnis verändert und welcher Fehler möglich ist.", "keyPoints": ["pcall fängt Laufzeitfehler einer Funktion ab und liefert Erfolg plus Ergebnis. Logge Fehler ohne Geheimnisse.", "Prüfe zuerst die Eingaben und den Fehlerfall, bevor du die Funktion in einer Resource verwendest."], "task": "Schreibe die gezeigte Lösung eigenständig und erzeuge die Ausgabe true. Erkläre anschließend, welche Zeile den entscheidenden Wert erzeugt.", "example": "local ok, value = pcall(tonumber,\"5\")\nprint(ok)", "starter": "-- Deine Lösung\n", "solution": "local ok, value = pcall(tonumber,\"5\")\nprint(ok)", "checks": ["tonumber", "local"], "hint": "Beginne mit dem ersten Wert und verfolge ihn bis zur Ausgabe. Vergleiche die Schreibweise mit dem Beispiel.", "mistake": "Ein kopierter Codeblock ohne Verständnis reicht nicht: prüfe Datentypen, Grenzen und Fehlerfall.", "quiz": "Was ist in diesem Thema besonders wichtig?", "options": ["Eingaben und Fehlerfälle prüfen, bevor Daten verarbeitet werden.", "Client-Daten sind automatisch sicher.", "Code braucht nie Tests."], "correct": 0, "reviewPrompt": "Welche Eingabe würde bei Fehler kontrolliert behandeln einen Fehler auslösen?", "duration": 12, "category": "Sprachen", "solutionOutput": "true"}'::jsonb) on conflict (lesson_id) do nothing;
