insert into public.ll_lesson_content(lesson_id,payload) values ('lua-54','{"id": "lua-54", "courseId": "lua", "title": "Daten prüfen vor Events", "lang": "lua", "level": "Senior", "chapterId": "lua-extension", "goal": "Du kannst daten prüfen vor events erklären und in einem eigenen Beispiel anwenden.", "theory": "Ein Client-Ereignis kann manipuliert werden. Werte und Berechtigung müssen serverseitig geprüft werden. Lies den Beispielcode Zeile für Zeile. Überlege, welche Eingabe das Ergebnis verändert und welcher Fehler möglich ist.", "keyPoints": ["Ein Client-Ereignis kann manipuliert werden. Werte und Berechtigung müssen serverseitig geprüft werden.", "Prüfe zuerst die Eingaben und den Fehlerfall, bevor du die Funktion in einer Resource verwendest."], "task": "Schreibe die gezeigte Lösung eigenständig und erzeuge die Ausgabe valid. Erkläre anschließend, welche Zeile den entscheidenden Wert erzeugt.", "example": "local amount = 5\nif type(amount) == \"number\" and amount > 0 then print(\"valid\") end", "starter": "-- Deine Lösung\n", "solution": "local amount = 5\nif type(amount) == \"number\" and amount > 0 then print(\"valid\") end", "checks": ["type", "local"], "hint": "Beginne mit dem ersten Wert und verfolge ihn bis zur Ausgabe. Vergleiche die Schreibweise mit dem Beispiel.", "mistake": "Ein kopierter Codeblock ohne Verständnis reicht nicht: prüfe Datentypen, Grenzen und Fehlerfall.", "quiz": "Was ist in diesem Thema besonders wichtig?", "options": ["Eingaben und Fehlerfälle prüfen, bevor Daten verarbeitet werden.", "Client-Daten sind automatisch sicher.", "Code braucht nie Tests."], "correct": 0, "reviewPrompt": "Welche Eingabe würde bei Daten prüfen vor Events einen Fehler auslösen?", "duration": 12, "category": "Sprachen", "solutionOutput": "valid"}'::jsonb) on conflict (lesson_id) do nothing;
