insert into public.ll_lesson_content(lesson_id,payload) values ('lua-55','{"id": "lua-55", "courseId": "lua", "title": "Client und Server trennen", "lang": "lua", "level": "Senior", "chapterId": "lua-extension", "goal": "Du kannst client und server trennen erklären und in einem eigenen Beispiel anwenden.", "theory": "Client-Code stellt die Oberfläche dar; der Server entscheidet über Geld und Inventar. Vertraue nie Client-Preisen. Lies den Beispielcode Zeile für Zeile. Überlege, welche Eingabe das Ergebnis verändert und welcher Fehler möglich ist.", "keyPoints": ["Client-Code stellt die Oberfläche dar; der Server entscheidet über Geld und Inventar. Vertraue nie Client-Preisen.", "Prüfe zuerst die Eingaben und den Fehlerfall, bevor du die Funktion in einer Resource verwendest."], "task": "Schreibe die gezeigte Lösung eigenständig und erzeuge die Ausgabe 50. Erkläre anschließend, welche Zeile den entscheidenden Wert erzeugt.", "example": "local serverPrice = 50\nprint(serverPrice)", "starter": "-- Deine Lösung\n", "solution": "local serverPrice = 50\nprint(serverPrice)", "checks": ["local"], "hint": "Beginne mit dem ersten Wert und verfolge ihn bis zur Ausgabe. Vergleiche die Schreibweise mit dem Beispiel.", "mistake": "Ein kopierter Codeblock ohne Verständnis reicht nicht: prüfe Datentypen, Grenzen und Fehlerfall.", "quiz": "Was ist in diesem Thema besonders wichtig?", "options": ["Eingaben und Fehlerfälle prüfen, bevor Daten verarbeitet werden.", "Client-Daten sind automatisch sicher.", "Code braucht nie Tests."], "correct": 0, "reviewPrompt": "Welche Eingabe würde bei Client und Server trennen einen Fehler auslösen?", "duration": 12, "category": "Sprachen", "solutionOutput": "50"}'::jsonb) on conflict (lesson_id) do nothing;
