insert into public.ll_lesson_content(lesson_id,payload) values ('lua-56','{"id": "lua-56", "courseId": "lua", "title": "Event-Namen strukturieren", "lang": "lua", "level": "Senior", "chapterId": "lua-extension", "goal": "Du kannst event-namen strukturieren erklären und in einem eigenen Beispiel anwenden.", "theory": "Ein Namensraum verhindert Kollisionen zwischen Resources. Nutze präzise, versionsfeste Namen. Lies den Beispielcode Zeile für Zeile. Überlege, welche Eingabe das Ergebnis verändert und welcher Fehler möglich ist.", "keyPoints": ["Ein Namensraum verhindert Kollisionen zwischen Resources. Nutze präzise, versionsfeste Namen.", "Prüfe zuerst die Eingaben und den Fehlerfall, bevor du die Funktion in einer Resource verwendest."], "task": "Schreibe die gezeigte Lösung eigenständig und erzeuge die Ausgabe sh_shop:purchase. Erkläre anschließend, welche Zeile den entscheidenden Wert erzeugt.", "example": "local eventName = \"sh_shop:purchase\"\nprint(eventName)", "starter": "-- Deine Lösung\n", "solution": "local eventName = \"sh_shop:purchase\"\nprint(eventName)", "checks": ["local"], "hint": "Beginne mit dem ersten Wert und verfolge ihn bis zur Ausgabe. Vergleiche die Schreibweise mit dem Beispiel.", "mistake": "Ein kopierter Codeblock ohne Verständnis reicht nicht: prüfe Datentypen, Grenzen und Fehlerfall.", "quiz": "Was ist in diesem Thema besonders wichtig?", "options": ["Eingaben und Fehlerfälle prüfen, bevor Daten verarbeitet werden.", "Client-Daten sind automatisch sicher.", "Code braucht nie Tests."], "correct": 0, "reviewPrompt": "Welche Eingabe würde bei Event-Namen strukturieren einen Fehler auslösen?", "duration": 12, "category": "Sprachen", "solutionOutput": "sh_shop:purchase"}'::jsonb) on conflict (lesson_id) do nothing;
