insert into public.ll_lesson_content(lesson_id,payload) values ('lua-57','{"id": "lua-57", "courseId": "lua", "title": "Ressourcen stoppen", "lang": "lua", "level": "Senior", "chapterId": "lua-extension", "goal": "Du kannst ressourcen stoppen erklären und in einem eigenen Beispiel anwenden.", "theory": "Registriere Aufräumlogik für Threads, Entities und Blips. Verwaiste Objekte kosten Leistung. Lies den Beispielcode Zeile für Zeile. Überlege, welche Eingabe das Ergebnis verändert und welcher Fehler möglich ist.", "keyPoints": ["Registriere Aufräumlogik für Threads, Entities und Blips. Verwaiste Objekte kosten Leistung.", "Prüfe zuerst die Eingaben und den Fehlerfall, bevor du die Funktion in einer Resource verwendest."], "task": "Schreibe die gezeigte Lösung eigenständig und erzeuge die Ausgabe false. Erkläre anschließend, welche Zeile den entscheidenden Wert erzeugt.", "example": "local active = false\nprint(active)", "starter": "-- Deine Lösung\n", "solution": "local active = false\nprint(active)", "checks": ["local"], "hint": "Beginne mit dem ersten Wert und verfolge ihn bis zur Ausgabe. Vergleiche die Schreibweise mit dem Beispiel.", "mistake": "Ein kopierter Codeblock ohne Verständnis reicht nicht: prüfe Datentypen, Grenzen und Fehlerfall.", "quiz": "Was ist in diesem Thema besonders wichtig?", "options": ["Eingaben und Fehlerfälle prüfen, bevor Daten verarbeitet werden.", "Client-Daten sind automatisch sicher.", "Code braucht nie Tests."], "correct": 0, "reviewPrompt": "Welche Eingabe würde bei Ressourcen stoppen einen Fehler auslösen?", "duration": 12, "category": "Sprachen", "solutionOutput": "false"}'::jsonb) on conflict (lesson_id) do nothing;
