insert into public.ll_lesson_content(lesson_id,payload) values ('lua-58','{"id": "lua-58", "courseId": "lua", "title": "Wait in Schleifen", "lang": "lua", "level": "Senior", "chapterId": "lua-extension", "goal": "Du kannst wait in schleifen erklären und in einem eigenen Beispiel anwenden.", "theory": "Ein Thread ohne Wait kann jeden Frame blockieren. Wähle ein Intervall passend zur benötigten Reaktion. Lies den Beispielcode Zeile für Zeile. Überlege, welche Eingabe das Ergebnis verändert und welcher Fehler möglich ist.", "keyPoints": ["Ein Thread ohne Wait kann jeden Frame blockieren. Wähle ein Intervall passend zur benötigten Reaktion.", "Prüfe zuerst die Eingaben und den Fehlerfall, bevor du die Funktion in einer Resource verwendest."], "task": "Schreibe die gezeigte Lösung eigenständig und erzeuge die Ausgabe 500. Erkläre anschließend, welche Zeile den entscheidenden Wert erzeugt.", "example": "local interval = 500\nprint(interval)", "starter": "-- Deine Lösung\n", "solution": "local interval = 500\nprint(interval)", "checks": ["local"], "hint": "Beginne mit dem ersten Wert und verfolge ihn bis zur Ausgabe. Vergleiche die Schreibweise mit dem Beispiel.", "mistake": "Ein kopierter Codeblock ohne Verständnis reicht nicht: prüfe Datentypen, Grenzen und Fehlerfall.", "quiz": "Was ist in diesem Thema besonders wichtig?", "options": ["Eingaben und Fehlerfälle prüfen, bevor Daten verarbeitet werden.", "Client-Daten sind automatisch sicher.", "Code braucht nie Tests."], "correct": 0, "reviewPrompt": "Welche Eingabe würde bei Wait in Schleifen einen Fehler auslösen?", "duration": 12, "category": "Sprachen", "solutionOutput": "500"}'::jsonb) on conflict (lesson_id) do nothing;
