insert into public.ll_lesson_content(lesson_id,payload) values ('lua-59','{"id": "lua-59", "courseId": "lua", "title": "Distanz effizient prüfen", "lang": "lua", "level": "Senior", "chapterId": "lua-extension", "goal": "Du kannst distanz effizient prüfen erklären und in einem eigenen Beispiel anwenden.", "theory": "Vergleiche nur notwendige Objekte und cache statische Positionen. Vermeide teure Arbeit in jedem Frame. Lies den Beispielcode Zeile für Zeile. Überlege, welche Eingabe das Ergebnis verändert und welcher Fehler möglich ist.", "keyPoints": ["Vergleiche nur notwendige Objekte und cache statische Positionen. Vermeide teure Arbeit in jedem Frame.", "Prüfe zuerst die Eingaben und den Fehlerfall, bevor du die Funktion in einer Resource verwendest."], "task": "Schreibe die gezeigte Lösung eigenständig und erzeuge die Ausgabe near. Erkläre anschließend, welche Zeile den entscheidenden Wert erzeugt.", "example": "local distance = 3\nif distance < 5 then print(\"near\") end", "starter": "-- Deine Lösung\n", "solution": "local distance = 3\nif distance < 5 then print(\"near\") end", "checks": ["local", "if"], "hint": "Beginne mit dem ersten Wert und verfolge ihn bis zur Ausgabe. Vergleiche die Schreibweise mit dem Beispiel.", "mistake": "Ein kopierter Codeblock ohne Verständnis reicht nicht: prüfe Datentypen, Grenzen und Fehlerfall.", "quiz": "Was ist in diesem Thema besonders wichtig?", "options": ["Eingaben und Fehlerfälle prüfen, bevor Daten verarbeitet werden.", "Client-Daten sind automatisch sicher.", "Code braucht nie Tests."], "correct": 0, "reviewPrompt": "Welche Eingabe würde bei Distanz effizient prüfen einen Fehler auslösen?", "duration": 12, "category": "Sprachen", "solutionOutput": "near"}'::jsonb) on conflict (lesson_id) do nothing;
