insert into public.ll_lesson_content(lesson_id,payload) values ('lua-60','{"id": "lua-60", "courseId": "lua", "title": "Konfiguration auslagern", "lang": "lua", "level": "Senior", "chapterId": "lua-extension", "goal": "Du kannst konfiguration auslagern erklären und in einem eigenen Beispiel anwenden.", "theory": "Konstanten gehören in eine gemeinsame Konfiguration. Prüfe Konfigurationswerte beim Laden. Lies den Beispielcode Zeile für Zeile. Überlege, welche Eingabe das Ergebnis verändert und welcher Fehler möglich ist.", "keyPoints": ["Konstanten gehören in eine gemeinsame Konfiguration. Prüfe Konfigurationswerte beim Laden.", "Prüfe zuerst die Eingaben und den Fehlerfall, bevor du die Funktion in einer Resource verwendest."], "task": "Schreibe die gezeigte Lösung eigenständig und erzeuge die Ausgabe 50. Erkläre anschließend, welche Zeile den entscheidenden Wert erzeugt.", "example": "local Config = {price = 50}\nprint(Config.price)", "starter": "-- Deine Lösung\n", "solution": "local Config = {price = 50}\nprint(Config.price)", "checks": ["local", "Config"], "hint": "Beginne mit dem ersten Wert und verfolge ihn bis zur Ausgabe. Vergleiche die Schreibweise mit dem Beispiel.", "mistake": "Ein kopierter Codeblock ohne Verständnis reicht nicht: prüfe Datentypen, Grenzen und Fehlerfall.", "quiz": "Was ist in diesem Thema besonders wichtig?", "options": ["Eingaben und Fehlerfälle prüfen, bevor Daten verarbeitet werden.", "Client-Daten sind automatisch sicher.", "Code braucht nie Tests."], "correct": 0, "reviewPrompt": "Welche Eingabe würde bei Konfiguration auslagern einen Fehler auslösen?", "duration": 12, "category": "Sprachen", "solutionOutput": "50"}'::jsonb) on conflict (lesson_id) do nothing;
