insert into public.ll_lesson_content(lesson_id,payload) values ('lua-61','{"id": "lua-61", "courseId": "lua", "title": "Serverseitige Transaktionen", "lang": "lua", "level": "Senior", "chapterId": "lua-extension", "goal": "Du kannst serverseitige transaktionen erklären und in einem eigenen Beispiel anwenden.", "theory": "Prüfe Kontostand, ziehe Geld ab und gewähre erst dann den Gegenstand. Doppelte Events dürfen keinen Bonus erzeugen. Lies den Beispielcode Zeile für Zeile. Überlege, welche Eingabe das Ergebnis verändert und welcher Fehler möglich ist.", "keyPoints": ["Prüfe Kontostand, ziehe Geld ab und gewähre erst dann den Gegenstand. Doppelte Events dürfen keinen Bonus erzeugen.", "Prüfe zuerst die Eingaben und den Fehlerfall, bevor du die Funktion in einer Resource verwendest."], "task": "Schreibe die gezeigte Lösung eigenständig und erzeuge die Ausgabe 20. Erkläre anschließend, welche Zeile den entscheidenden Wert erzeugt.", "example": "local balance = 70\nlocal price = 50\nif balance >= price then print(balance-price) end", "starter": "-- Deine Lösung\n", "solution": "local balance = 70\nlocal price = 50\nif balance >= price then print(balance-price) end", "checks": ["local", ">="], "hint": "Beginne mit dem ersten Wert und verfolge ihn bis zur Ausgabe. Vergleiche die Schreibweise mit dem Beispiel.", "mistake": "Ein kopierter Codeblock ohne Verständnis reicht nicht: prüfe Datentypen, Grenzen und Fehlerfall.", "quiz": "Was ist in diesem Thema besonders wichtig?", "options": ["Eingaben und Fehlerfälle prüfen, bevor Daten verarbeitet werden.", "Client-Daten sind automatisch sicher.", "Code braucht nie Tests."], "correct": 0, "reviewPrompt": "Welche Eingabe würde bei Serverseitige Transaktionen einen Fehler auslösen?", "duration": 12, "category": "Sprachen", "solutionOutput": "20"}'::jsonb) on conflict (lesson_id) do nothing;
