insert into public.ll_lesson_content(lesson_id,payload) values ('lua-62','{"id": "lua-62", "courseId": "lua", "title": "Eingaben begrenzen", "lang": "lua", "level": "Senior", "chapterId": "lua-extension", "goal": "Du kannst eingaben begrenzen erklären und in einem eigenen Beispiel anwenden.", "theory": "Zahlen brauchen Mindest- und Höchstwerte. Text braucht Längen- und Formatprüfung vor Datenbankzugriff. Lies den Beispielcode Zeile für Zeile. Überlege, welche Eingabe das Ergebnis verändert und welcher Fehler möglich ist.", "keyPoints": ["Zahlen brauchen Mindest- und Höchstwerte. Text braucht Längen- und Formatprüfung vor Datenbankzugriff.", "Prüfe zuerst die Eingaben und den Fehlerfall, bevor du die Funktion in einer Resource verwendest."], "task": "Schreibe die gezeigte Lösung eigenständig und erzeuge die Ausgabe ok. Erkläre anschließend, welche Zeile den entscheidenden Wert erzeugt.", "example": "local amount = 3\nif amount >= 1 and amount <= 10 then print(\"ok\") end", "starter": "-- Deine Lösung\n", "solution": "local amount = 3\nif amount >= 1 and amount <= 10 then print(\"ok\") end", "checks": ["local", ">="], "hint": "Beginne mit dem ersten Wert und verfolge ihn bis zur Ausgabe. Vergleiche die Schreibweise mit dem Beispiel.", "mistake": "Ein kopierter Codeblock ohne Verständnis reicht nicht: prüfe Datentypen, Grenzen und Fehlerfall.", "quiz": "Was ist in diesem Thema besonders wichtig?", "options": ["Eingaben und Fehlerfälle prüfen, bevor Daten verarbeitet werden.", "Client-Daten sind automatisch sicher.", "Code braucht nie Tests."], "correct": 0, "reviewPrompt": "Welche Eingabe würde bei Eingaben begrenzen einen Fehler auslösen?", "duration": 12, "category": "Sprachen", "solutionOutput": "ok"}'::jsonb) on conflict (lesson_id) do nothing;
