insert into public.ll_lesson_content(lesson_id,payload) values ('lua-63','{"id": "lua-63", "courseId": "lua", "title": "Fehlerfälle testen", "lang": "lua", "level": "Senior", "chapterId": "lua-extension", "goal": "Du kannst fehlerfälle testen erklären und in einem eigenen Beispiel anwenden.", "theory": "Teste fehlende Spieler, falsche Typen, negative Werte und doppelte Anfragen. Ein Erfolgstest allein genügt nicht. Lies den Beispielcode Zeile für Zeile. Überlege, welche Eingabe das Ergebnis verändert und welcher Fehler möglich ist.", "keyPoints": ["Teste fehlende Spieler, falsche Typen, negative Werte und doppelte Anfragen. Ein Erfolgstest allein genügt nicht.", "Prüfe zuerst die Eingaben und den Fehlerfall, bevor du die Funktion in einer Resource verwendest."], "task": "Schreibe die gezeigte Lösung eigenständig und erzeuge die Ausgabe reject. Erkläre anschließend, welche Zeile den entscheidenden Wert erzeugt.", "example": "local amount = -1\nif amount < 1 then print(\"reject\") end", "starter": "-- Deine Lösung\n", "solution": "local amount = -1\nif amount < 1 then print(\"reject\") end", "checks": ["local", "if"], "hint": "Beginne mit dem ersten Wert und verfolge ihn bis zur Ausgabe. Vergleiche die Schreibweise mit dem Beispiel.", "mistake": "Ein kopierter Codeblock ohne Verständnis reicht nicht: prüfe Datentypen, Grenzen und Fehlerfall.", "quiz": "Was ist in diesem Thema besonders wichtig?", "options": ["Eingaben und Fehlerfälle prüfen, bevor Daten verarbeitet werden.", "Client-Daten sind automatisch sicher.", "Code braucht nie Tests."], "correct": 0, "reviewPrompt": "Welche Eingabe würde bei Fehlerfälle testen einen Fehler auslösen?", "duration": 12, "category": "Sprachen", "solutionOutput": "reject"}'::jsonb) on conflict (lesson_id) do nothing;
