insert into public.ll_lesson_content(lesson_id,payload) values ('lua-64','{"id": "lua-64", "courseId": "lua", "title": "Logs verständlich machen", "lang": "lua", "level": "Senior", "chapterId": "lua-extension", "goal": "Du kannst logs verständlich machen erklären und in einem eigenen Beispiel anwenden.", "theory": "Ein Log soll Kontext und Ursache nennen, aber keine Tokens oder Passwörter verraten. Verwende einheitliche Meldungen. Lies den Beispielcode Zeile für Zeile. Überlege, welche Eingabe das Ergebnis verändert und welcher Fehler möglich ist.", "keyPoints": ["Ein Log soll Kontext und Ursache nennen, aber keine Tokens oder Passwörter verraten. Verwende einheitliche Meldungen.", "Prüfe zuerst die Eingaben und den Fehlerfall, bevor du die Funktion in einer Resource verwendest."], "task": "Schreibe die gezeigte Lösung eigenständig und erzeuge die Ausgabe error: sh_shop. Erkläre anschließend, welche Zeile den entscheidenden Wert erzeugt.", "example": "local resource = \"sh_shop\"\nprint(\"error: \" .. resource)", "starter": "-- Deine Lösung\n", "solution": "local resource = \"sh_shop\"\nprint(\"error: \" .. resource)", "checks": ["local", "or"], "hint": "Beginne mit dem ersten Wert und verfolge ihn bis zur Ausgabe. Vergleiche die Schreibweise mit dem Beispiel.", "mistake": "Ein kopierter Codeblock ohne Verständnis reicht nicht: prüfe Datentypen, Grenzen und Fehlerfall.", "quiz": "Was ist in diesem Thema besonders wichtig?", "options": ["Eingaben und Fehlerfälle prüfen, bevor Daten verarbeitet werden.", "Client-Daten sind automatisch sicher.", "Code braucht nie Tests."], "correct": 0, "reviewPrompt": "Welche Eingabe würde bei Logs verständlich machen einen Fehler auslösen?", "duration": 12, "category": "Sprachen", "solutionOutput": "error: sh_shop"}'::jsonb) on conflict (lesson_id) do nothing;
