insert into public.ll_lesson_content(lesson_id,payload) values ('lua-65','{"id": "lua-65", "courseId": "lua", "title": "Module sinnvoll aufteilen", "lang": "lua", "level": "Senior", "chapterId": "lua-extension", "goal": "Du kannst module sinnvoll aufteilen erklären und in einem eigenen Beispiel anwenden.", "theory": "Trenne Datenzugriff, Spiellogik und UI. Jede Datei braucht eine klare Verantwortung. Lies den Beispielcode Zeile für Zeile. Überlege, welche Eingabe das Ergebnis verändert und welcher Fehler möglich ist.", "keyPoints": ["Trenne Datenzugriff, Spiellogik und UI. Jede Datei braucht eine klare Verantwortung.", "Prüfe zuerst die Eingaben und den Fehlerfall, bevor du die Funktion in einer Resource verwendest."], "task": "Schreibe die gezeigte Lösung eigenständig und erzeuge die Ausgabe shopService. Erkläre anschließend, welche Zeile den entscheidenden Wert erzeugt.", "example": "local module = \"shopService\"\nprint(module)", "starter": "-- Deine Lösung\n", "solution": "local module = \"shopService\"\nprint(module)", "checks": ["local"], "hint": "Beginne mit dem ersten Wert und verfolge ihn bis zur Ausgabe. Vergleiche die Schreibweise mit dem Beispiel.", "mistake": "Ein kopierter Codeblock ohne Verständnis reicht nicht: prüfe Datentypen, Grenzen und Fehlerfall.", "quiz": "Was ist in diesem Thema besonders wichtig?", "options": ["Eingaben und Fehlerfälle prüfen, bevor Daten verarbeitet werden.", "Client-Daten sind automatisch sicher.", "Code braucht nie Tests."], "correct": 0, "reviewPrompt": "Welche Eingabe würde bei Module sinnvoll aufteilen einen Fehler auslösen?", "duration": 12, "category": "Sprachen", "solutionOutput": "shopService"}'::jsonb) on conflict (lesson_id) do nothing;
