insert into public.ll_lesson_content(lesson_id,payload) values ('lua-66','{"id": "lua-66", "courseId": "lua", "title": "Tests automatisieren", "lang": "lua", "level": "Senior", "chapterId": "lua-extension", "goal": "Du kannst tests automatisieren erklären und in einem eigenen Beispiel anwenden.", "theory": "Prüfe Kernfunktionen mit Beispieldaten. Halte erwartete Ergebnisse im Test fest, damit Änderungen Regressionen zeigen. Lies den Beispielcode Zeile für Zeile. Überlege, welche Eingabe das Ergebnis verändert und welcher Fehler möglich ist.", "keyPoints": ["Prüfe Kernfunktionen mit Beispieldaten. Halte erwartete Ergebnisse im Test fest, damit Änderungen Regressionen zeigen.", "Prüfe zuerst die Eingaben und den Fehlerfall, bevor du die Funktion in einer Resource verwendest."], "task": "Schreibe die gezeigte Lösung eigenständig und erzeuge die Ausgabe pass. Erkläre anschließend, welche Zeile den entscheidenden Wert erzeugt.", "example": "local function sum(a,b) return a+b end\nassert(sum(2,3) == 5)\nprint(\"pass\")", "starter": "-- Deine Lösung\n", "solution": "local function sum(a,b) return a+b end\nassert(sum(2,3) == 5)\nprint(\"pass\")", "checks": ["local", "=="], "hint": "Beginne mit dem ersten Wert und verfolge ihn bis zur Ausgabe. Vergleiche die Schreibweise mit dem Beispiel.", "mistake": "Ein kopierter Codeblock ohne Verständnis reicht nicht: prüfe Datentypen, Grenzen und Fehlerfall.", "quiz": "Was ist in diesem Thema besonders wichtig?", "options": ["Eingaben und Fehlerfälle prüfen, bevor Daten verarbeitet werden.", "Client-Daten sind automatisch sicher.", "Code braucht nie Tests."], "correct": 0, "reviewPrompt": "Welche Eingabe würde bei Tests automatisieren einen Fehler auslösen?", "duration": 12, "category": "Sprachen", "solutionOutput": "pass"}'::jsonb) on conflict (lesson_id) do nothing;
