insert into public.ll_lesson_content(lesson_id,payload) values ('lua-67','{"id": "lua-67", "courseId": "lua", "title": "Performance messen", "lang": "lua", "level": "Senior", "chapterId": "lua-extension", "goal": "Du kannst performance messen erklären und in einem eigenen Beispiel anwenden.", "theory": "Messe zuerst einen Engpass, bevor du optimierst. Cache nur Daten, deren Gültigkeit du kontrollierst. Lies den Beispielcode Zeile für Zeile. Überlege, welche Eingabe das Ergebnis verändert und welcher Fehler möglich ist.", "keyPoints": ["Messe zuerst einen Engpass, bevor du optimierst. Cache nur Daten, deren Gültigkeit du kontrollierst.", "Prüfe zuerst die Eingaben und den Fehlerfall, bevor du die Funktion in einer Resource verwendest."], "task": "Schreibe die gezeigte Lösung eigenständig und erzeuge die Ausgabe 1000. Erkläre anschließend, welche Zeile den entscheidenden Wert erzeugt.", "example": "local interval = 1000\nprint(interval)", "starter": "-- Deine Lösung\n", "solution": "local interval = 1000\nprint(interval)", "checks": ["local"], "hint": "Beginne mit dem ersten Wert und verfolge ihn bis zur Ausgabe. Vergleiche die Schreibweise mit dem Beispiel.", "mistake": "Ein kopierter Codeblock ohne Verständnis reicht nicht: prüfe Datentypen, Grenzen und Fehlerfall.", "quiz": "Was ist in diesem Thema besonders wichtig?", "options": ["Eingaben und Fehlerfälle prüfen, bevor Daten verarbeitet werden.", "Client-Daten sind automatisch sicher.", "Code braucht nie Tests."], "correct": 0, "reviewPrompt": "Welche Eingabe würde bei Performance messen einen Fehler auslösen?", "duration": 12, "category": "Sprachen", "solutionOutput": "1000"}'::jsonb) on conflict (lesson_id) do nothing;
