insert into public.ll_lesson_content(lesson_id,payload) values ('lua-69','{"id": "lua-69", "courseId": "lua", "title": "Sicherheitsreview", "lang": "lua", "level": "Senior", "chapterId": "lua-extension", "goal": "Du kannst sicherheitsreview erklären und in einem eigenen Beispiel anwenden.", "theory": "Kontrolliere Eingaben, Berechtigungen, Geheimnisse und Event-Spam vor einer Veröffentlichung. Dokumentiere Grenzen. Lies den Beispielcode Zeile für Zeile. Überlege, welche Eingabe das Ergebnis verändert und welcher Fehler möglich ist.", "keyPoints": ["Kontrolliere Eingaben, Berechtigungen, Geheimnisse und Event-Spam vor einer Veröffentlichung. Dokumentiere Grenzen.", "Prüfe zuerst die Eingaben und den Fehlerfall, bevor du die Funktion in einer Resource verwendest."], "task": "Schreibe die gezeigte Lösung eigenständig und erzeuge die Ausgabe reviewed. Erkläre anschließend, welche Zeile den entscheidenden Wert erzeugt.", "example": "local authorized = true\nif authorized then print(\"reviewed\") end", "starter": "-- Deine Lösung\n", "solution": "local authorized = true\nif authorized then print(\"reviewed\") end", "checks": ["local", "or"], "hint": "Beginne mit dem ersten Wert und verfolge ihn bis zur Ausgabe. Vergleiche die Schreibweise mit dem Beispiel.", "mistake": "Ein kopierter Codeblock ohne Verständnis reicht nicht: prüfe Datentypen, Grenzen und Fehlerfall.", "quiz": "Was ist in diesem Thema besonders wichtig?", "options": ["Eingaben und Fehlerfälle prüfen, bevor Daten verarbeitet werden.", "Client-Daten sind automatisch sicher.", "Code braucht nie Tests."], "correct": 0, "reviewPrompt": "Welche Eingabe würde bei Sicherheitsreview einen Fehler auslösen?", "duration": 12, "category": "Sprachen", "solutionOutput": "reviewed"}'::jsonb) on conflict (lesson_id) do nothing;
