insert into public.ll_lesson_content(lesson_id,payload) values ('lua-70','{"id": "lua-70", "courseId": "lua", "title": "Senior-Projekt: Release", "lang": "lua", "level": "Senior", "chapterId": "lua-extension", "goal": "Du kannst senior-projekt: release erklären und in einem eigenen Beispiel anwenden.", "theory": "Baue ein überprüfbares Shop-Feature mit Tests, Logs, Dokumentation und Rollback. Jede Änderung braucht einen nachvollziehbaren Zweck. Lies den Beispielcode Zeile für Zeile. Überlege, welche Eingabe das Ergebnis verändert und welcher Fehler möglich ist.", "keyPoints": ["Baue ein überprüfbares Shop-Feature mit Tests, Logs, Dokumentation und Rollback. Jede Änderung braucht einen nachvollziehbaren Zweck.", "Prüfe zuerst die Eingaben und den Fehlerfall, bevor du die Funktion in einer Resource verwendest."], "task": "Schreibe die gezeigte Lösung eigenständig und erzeuge die Ausgabe 1.0.0. Erkläre anschließend, welche Zeile den entscheidenden Wert erzeugt.", "example": "local release = \"1.0.0\"\nprint(release)", "starter": "-- Deine Lösung\n", "solution": "local release = \"1.0.0\"\nprint(release)", "checks": ["local"], "hint": "Beginne mit dem ersten Wert und verfolge ihn bis zur Ausgabe. Vergleiche die Schreibweise mit dem Beispiel.", "mistake": "Ein kopierter Codeblock ohne Verständnis reicht nicht: prüfe Datentypen, Grenzen und Fehlerfall.", "quiz": "Was ist in diesem Thema besonders wichtig?", "options": ["Eingaben und Fehlerfälle prüfen, bevor Daten verarbeitet werden.", "Client-Daten sind automatisch sicher.", "Code braucht nie Tests."], "correct": 0, "reviewPrompt": "Welche Eingabe würde bei Senior-Projekt: Release einen Fehler auslösen?", "duration": 12, "category": "Sprachen", "solutionOutput": "1.0.0"}'::jsonb) on conflict (lesson_id) do nothing;
